'use strict';
const mounts={Ceiling:{left:'SVQ-CB-L-RPL',right:'SVQ-CB-R-RPL',sub:'WIN-BRK-100C'},Fascia:{left:'SVQ-FBA20L-RPL',right:'SVQ-FBA20R-RPL',sub:'WIN-BRK-100F'},Pocket:{left:'SVQ-PB-L-RPL',right:'SVQ-PB-R-RPL',sub:'WIN-BRK-100P'},Wall:{left:'SVQ-WB-L-RPL',right:'SVQ-WB-R-RPL',sub:'WIN-BRK-100W'},Jamb:{left:'SVQ-WB-L-RPL',right:'SVQ-WB-R-RPL',sub:'WIN-BRK-100J'}};
const quoteLines=[{"id":1,"area":"Kitchen","product":"Roller 100","mount":"Fascia","communication":"Wired","driveSide":"Left"},{"id":2,"area":"Bedroom","product":"Roller 100","mount":"Pocket","communication":"Wireless","driveSide":"Right"},{"id":3,"area":"Dining room","product":"Roller 64","mount":"Ceiling","communication":"Wired","driveSide":"Right"},{"id":4,"area":"Office","product":"Roller 20","mount":"Wall","communication":"Battery","driveSide":"Left"},{"id":5,"area":"Guest bedroom","product":"Triathlon","mount":"Inside","communication":"Wireless","driveSide":"Right"},{"id":6,"area":"Primary suite","product":"Palladiom Wire-Free","mount":"Jamb","communication":"Wire-Free","driveSide":"Left"},{"id":7,"area":"Breakfast nook","product":"Roller 64","mount":"Wall","communication":"Wireless","driveSide":"Left"},{"id":8,"area":"Study","product":"Roller 20","mount":"Ceiling","communication":"Wired","driveSide":"Right"},{"id":9,"area":"Family room","product":"Triathlon","mount":"Outside","communication":"Battery","driveSide":"Left"},{"id":10,"area":"Entry hall","product":"Palladiom Wire-Free","mount":"Wall","communication":"Wire-Free","driveSide":"Right"},{"id":11,"area":"Media room","product":"Roller 64","mount":"Fascia","communication":"Wired","driveSide":"Right"},{"id":12,"area":"Loft","product":"Roller 20","mount":"Jamb","communication":"Wired","driveSide":"Left"},{"id":13,"area":"Guest suite","product":"Triathlon","mount":"Inside","communication":"Battery","driveSide":"Right"},{"id":14,"area":"Lounge","product":"Palladiom Wire-Free","mount":"Ceiling","communication":"Battery","driveSide":"Left"},{"id":15,"area":"Upper landing","product":"Roller 64","mount":"Pocket","communication":"Wireless","driveSide":"Right"},{"id":16,"area":"Living Room","product":"Roller 100","mount":"Ceiling","communication":"Wired","driveSide":"Left"}];
function selectedQuoteLine(){return quoteLines.find(line=>line.id===state.line)}
const state={page:'login',mount:null,expanded:false,cart:[],source:'Parts directory',line:null,selectedLines:[],replacementMethod:null,product:'All products',family:'All type groups',partType:'All parts',filterMount:'All mounts',color:'All colors',query:'',email:'',shade:'Drapery',assistant:[],quoteName:'Sample quote.pdf',side:'Both',includeShade:true,includeSub:true};
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,action,cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,action,extra='')=>btn(text,action,'link',extra);
const copy=code=>btn(icon('Copy')+'<span>Copy</span>','copy','copy',`data-code="${esc(code)}" aria-label="Copy ${esc(code)}"`);
const productPill=(name,cls='')=>`<span class="${(cls.includes('product-card-system')||cls.includes('quote-product-tag'))?'product-pill':'product-text'} ${cls}">${esc(name)}</span>`;
function productTitle(name,mount,outlined=true){return `${outlined?productPill(name,'product-title-pill'):`<span class="product-primary-title">${esc(name)}</span>`}${mount?`<span class="product-mount-label">${esc(mount)} Mount</span>`:''}`}
const brand=()=>`<span class="brand"><b class="wordmark">${icon('Sun')}LUTRON</b><span class="bar"></span><span>Particle</span></span>`;
const select=(label,id,values,value)=>`<label class="label" for="${id}">${label}</label><select id="${id}" data-field="${id}">${values.map(x=>`<option value="${esc(x)}" ${value===x?'selected':''}>${esc(['family','partType','filterMount','color'].includes(id)&&x.startsWith('All ')?'Show all':x)}</option>`).join('')}</select>`;
function header(){return `<header class="header">${btn(brand(),'home','brand','aria-label="Particle home"')}<nav aria-label="Main navigation">${btn(icon('House')+'<span>Home</span>','home')}${btn(icon('CircleHelp')+'<span>Help</span>','help')}${btn('<span class="avatar">KF</span><span>Kenneth</span>','profile')}</nav></header><div class="demo-ribbon">Interactive prototype · Sample data</div>`}
function crumbs(current){return `<nav class="breadcrumbs" aria-label="Breadcrumb">${link('Home','home')}<span class="crumbsep">›</span>${link('Find a part','entry')}${current?`<span class="crumbsep">›</span><span>${current}</span>`:''}</nav>`}
function title(h,p='',action=''){return `<div class="titlebar"><div><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>${action}</div>`}
function resetDirectory(){Object.assign(state,{mount:null,expanded:false,product:'All products',family:'All type groups',partType:'All parts',filterMount:'All mounts',color:'All colors',query:''})}
const viewHistory=[];let currentView=null,restoringView=false,modalHistory=[],currentModalState=null;
function captureView(){const {cart,email,...viewState}=state;return {state:structuredClone(viewState),components:{selectionKey:componentView.selectionKey,openLines:[...componentView.openLines],openDetails:[...componentView.openDetails]},scroll:window.scrollY}}
function viewKey(view){const s=view.state;return JSON.stringify([s.page,['directory','focused','selection'].includes(s.page)?[s.mount,s.expanded]:null,s.page==='directory'?[s.product,s.family,s.partType,s.filterMount,s.color,!!s.query.trim()]:null,s.page==='assistant'?s.assistant:null,s.page==='builder'?s.shade:null])}
function rememberView(){const next=captureView();if(!restoringView&&currentView&&viewKey(currentView)!==viewKey(next)&&currentView.state.page!=='processing'){viewHistory.push(currentView);if(viewHistory.length>100)viewHistory.shift()}currentView=next}
function syncCurrentView(){if(currentView&&currentView.state.page===state.page){currentView=captureView()}}
function backControl(){return btn(icon('ChevronRight','back-arrow')+'<span>Go Back</span>','go-back','go-back-button',viewHistory.length?'':'disabled aria-label="Go Back — no previous view"')}
function goBack(){const modal=$('#modal');if(modal.open){if(modalHistory.length){const previous=modalHistory.pop();if(previous.coverage){Object.assign(state,previous.coverage);render()}modal.innerHTML=previous.html;menuState=structuredClone(previous.menu);currentModalState={menu:structuredClone(menuState)};modal.scrollTop=previous.scroll}else modal.close();return}const previous=viewHistory.pop();if(!previous)return;restoringView=true;Object.assign(state,previous.state);Object.assign(componentView,{selectionKey:previous.components.selectionKey,openLines:new Set(previous.components.openLines),openDetails:new Set(previous.components.openDetails)});render();restoringView=false;window.scrollTo({top:previous.scroll,behavior:'instant'});currentView=captureView()}
function navigate(page,query){if(page==='selection'){showBracketSelection();return}if(page==='components'&&state.page!=='components'){componentView.openLines.clear();componentView.openDetails.clear()}if(page==='focused')state.expanded=false;if(page==='directory'){resetDirectory();if(query)state.query=query}state.page=page;if($('#modal').open)$('#modal').close();render();window.scrollTo({top:0,behavior:'instant'})}
function toast(text,undo){const box=$('#toast');clearTimeout(toast.timer);box.className='toast';box.innerHTML=`<span>${esc(text)}</span>${undo?btn('Undo','undo'):''}`;toast.undo=undo;toast.timer=setTimeout(()=>{box.className='';box.innerHTML=''},6500)}
function partEntries(m){const d=mounts[m];return [{code:d.left,name:`Roller 100 On-shade Brackets — ${m} Mount, Left`,unit:'each'},{code:d.right,name:`Roller 100 On-shade Brackets — ${m} Mount, Right`,unit:'each'},{code:d.sub,name:`Roller 100 Mounting Sub-Bracket — ${m} Mount`,unit:'kit'}]}
function addParts(entries,bundle){const before=structuredClone(state.cart);entries.forEach(e=>{const found=state.cart.find(x=>x.code===e.code);if(found){found.qty++;if(!found.sources.includes(state.source))found.sources.push(state.source)}else state.cart.push({...e,qty:1,sources:[state.source],bundle:bundle||''})});renderCart();toast(bundle?`${bundle} added · ${entries.length} part numbers`:`${entries[0].code} added to your list`,()=>{state.cart=before;render();toast('Addition undone')})}
function cart(){return `<aside class="panel cart" aria-label="Replacement list"><div class="cart-header"><h2>Replacement list</h2><small class="count-badge">${state.cart.length} part number${state.cart.length===1?'':'s'}</small></div>${state.cart.length?`<div class="cart-items">${state.cart.map((x,i)=>`<div class="cart-item"><h3>${productPill(x.name)}</h3><div class="partcode">${esc(x.code)}</div><small>${esc(x.sources.join(' · '))}</small><div class="cart-controls"><div class="row"><div class="qty">${btn('−','qty','','data-index="'+i+'" data-delta="-1" aria-label="Decrease quantity"')}<input aria-label="Quantity of ${esc(x.code)}" type="number" min="1" max="999" value="${x.qty}" data-qty="${i}">${btn('+','qty','','data-index="'+i+'" data-delta="1" aria-label="Increase quantity"')}</div><small>${x.unit}</small></div>${link('Remove','remove',`data-index="${i}"`)}</div></div>`).join('')}</div>${btn('Review parts','review','primary')}<p class="center meta small-gap">Export a CSV after review.</p>`:`<div class="empty"><div class="empty-icon">${icon('ListPlus')}</div><h3 class="empty-list-heading">Start adding parts</h3><p class="small-gap">Parts you add will stay here as you browse.</p></div>${btn('Review parts','review','primary','disabled')}`}</aside>`}
function renderCart(){const c=$('.cart');if(c)c.outerHTML=cart();if(state.page==='review')render();else stampFeatures()}
function login(){return `<main class="login"><form class="login-box" id="login-form"><h1 class="login-hero">${brand()}</h1><label class="label" for="email">Enter Email</label><input id="email" type="email" placeholder="name@lutron.com" autocomplete="email" value="${esc(state.email)}"><button class="primary" type="submit">Continue</button><p class="meta">Demo access · No email will be sent</p><div class="login-help">${btn(icon('CircleHelp')+'<span>Need help signing in?</span>','signin-help','link')}</div></form></main>`}
function home(){return `<main class="page"><div class="home"><div class="home-title"><p>Welcome, Kenneth</p><h1>Keep Calm &amp; Lutron</h1></div><section class="panel tasks">${[['Search','Find a part','Search by part number, browse by product, or start with a quote.','entry','Launch Part Pilot'],['Blinds','Build a shade','Complete shading configuration engine.','builder','Launch Shade Builder'],['FileText','Request engineering review','Prepare a Customer Shading Request with CSR Automate.','csr','Launch CSR Automate']].map(([ic,h,p,a,cta])=>btn(`<span class="task-icon">${icon(ic)}</span><span class="task-copy"><h2>${h}</h2><p>${p}</p></span><span class="task-action"><span>${cta}</span>${icon('ChevronRight','task-action-arrow')}</span>`,a,'task')).join('')}</section></div></main>`}
function entry(){return `<main class="page entry" aria-label="Find replacement parts">${crumbs('')}<div class="entry-grid"><section class="panel entry-card entry-quote"><span class="task-icon">${icon('FileText')}</span><div class="entry-card-body"><h2>Start with a quote</h2><p>Find the shade in your PDF and choose the parts to replace.</p>${btn('Upload quote','upload','entry-pill')}</div>${reference('P03-FIND-PART-QUOTE')}</section><section class="panel entry-card entry-product"><span class="task-icon">${icon('Layers')}</span><div class="entry-card-body"><h2>Browse parts directory</h2><p>Filter by product, mounting condition, or part type.</p>${btn('Browse products','directory','entry-pill')}</div>${reference('P03-FIND-PART-PRODUCT')}</section><section class="panel entry-card entry-part-number"><span class="task-icon">${icon('Search')}</span><div class="entry-card-body"><h2>Search by part number</h2><p>Have a part number? Enter all or part of it to find a match.</p>${btn('Enter part number','part-number-search','entry-pill','aria-haspopup="dialog"')}</div>${reference('P03-FIND-PART-PART-NUMBER')}</section></div><aside class="entry-assistant-callout"><span class="entry-assistant-icon">${icon('CircleHelp')}</span><h2>Not sure what you need? We got you.</h2>${btn('Launch Part Pilot','assistant','entry-assistant-action')}</aside></main>`}
const directoryFilters={family:{label:'Filter by product family',title:'Choose product families',all:'All type groups',color:'pink',options:['All type groups','Roller Shades','Drapery','Wood Blinds','Roman Shades','Honeycomb Shades'],reference:'M-PRODUCT-GROUP-FILTER'},product:{label:'Filter by system type',title:'Choose system types',all:'All products',options:['All products','Roller 20','Roller 64','Roller 100','Roller 150','Roller 300','Triathlon','Palladiom','Palladiom Wire-Free'],reference:'M-PRODUCT-FILTER'},partType:{label:'Part type',title:'Choose part types',all:'All parts',color:'green',options:['All parts','On-shade brackets','Mounting sub-brackets','Endcaps','Drives','Coupled shade components'],reference:'M-PART-TYPE-FILTER'},filterMount:{label:'Mounting condition',title:'Choose mounting conditions',all:'All mounts',options:['All mounts',...Object.keys(mounts)],reference:'M-MOUNT-FILTER'},color:{label:'Finish',title:'Choose finishes',all:'All colors',options:['All colors','White'],reference:'M-FINISH-FILTER'}};
function filterValues(field){const value=state[field],config=directoryFilters[field];return Array.isArray(value)?value:value===config.all?[]:[value]}
let filterDraft=null;
function directoryFilterTrigger(field){const config=directoryFilters[field],values=filterValues(field);return `<span class="label" id="${field}-filter-label">${config.label}</span>${btn(`<span id="${field}-filter-value" class="filter-trigger-values">${values.length?values.map(value=>`<span class="${config.color?'filter-value-chip filter-'+config.color:''}">${esc(value)}</span>`).join(config.color?'':', '):'Show all'}</span>${icon('ChevronDown')}`,'filter-menu','product-filter-trigger',`id="${field}-filter-trigger" data-filter="${field}" aria-haspopup="dialog" aria-labelledby="${field}-filter-label ${field}-filter-value"`)}`}
function openDirectoryFilter(field){const config=directoryFilters[field];if(!config)return;filterDraft={field,values:[...filterValues(field)]};renderDirectoryFilter()}
function renderDirectoryFilter(refresh=false){const {field,values}=filterDraft,config=directoryFilters[field];openModal(modalFrame(config.title,`<p class="filter-selection-hint">Select one or more options, then apply your filter.</p><div class="${config.color?'filter-pill-cluster':'filter-text-list'}" role="group" aria-label="${config.label}">${config.options.map(value=>{const selected=value===config.all?!values.length:values.includes(value);return btn(`${selected?icon('Check'):''}<span>${esc(value===config.all?'Show all':value)}</span>`,'filter-pick',(config.color?'filter-option-pill filter-'+config.color:'filter-text-option')+(selected?' current':''),`data-filter="${field}" data-value="${value}" aria-pressed="${selected}"`)}).join('')}</div>${field==='color'?'<p class="meta small-gap">Finish filtering is illustrative in this prototype.</p>':''}<div class="filter-apply-row"><span class="meta" aria-live="polite">${values.length?values.length+' selected':'Showing all'}</span>${btn('Filter','filter-apply','primary',`data-filter="${field}"`)}</div>`,config.reference),refresh)}
function filters(){return `<aside class="panel filters"><div class="row between"><h3>Filter parts</h3>${link('Clear','clear-filters')}</div>${['family','product','partType'].map(directoryFilterTrigger).join('')}<details class="filterdetail" ${filterValues('filterMount').length?'open':''}><summary>Mount type</summary>${directoryFilterTrigger('filterMount')}</details><details class="filterdetail" ${filterValues('color').length?'open':''}><summary>Color</summary>${directoryFilterTrigger('color')}<p class="meta small-gap">Finish filtering is illustrative in this prototype.</p></details></aside>`}
function activeFilterTags(){return Object.keys(directoryFilters).flatMap(field=>filterValues(field).map(value=>`<span class="tag">${esc(value)} ${btn('×','clear-filter-value','',`data-filter="${field}" data-value="${esc(value)}" aria-label="Remove ${esc(value)} filter"`)}</span>`)).join('')}
function searchBar(id='query',value=state.query){return `<div class="search-wrap"><form class="search" id="${id==='query'?'directory-search':'entry-search'}"><span class="search-icon">${icon('Search')}</span><label class="sr-only" for="${id}">Search product name, mount type, or part number</label><input id="${id}" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}-suggestions" placeholder="Search product, mount type, or part number" value="${esc(value)}"><button type="submit" class="primary">Search</button></form><div class="search-suggestions" id="${id}-suggestions" hidden></div></div>`}
function openPartNumberSearch(){const form=searchBar('entryquery','').replace('Search product name, mount type, or part number','Part number').replace('placeholder="Search product, mount type, or part number"','placeholder="e.g. SVQ-CB-L-RPL" data-part-number="true" required pattern=".*\\S.*" spellcheck="false"');openModal(modalFrame('Search by part number',`<section class="part-number-search"><p class="part-number-intro">Type or paste a full or partial part number. Select a match or search to see results.</p>${form}</section>`,'M-PART-NUMBER-SEARCH'));$('#entryquery').focus()}
const catalog=[{name:'Roller 100 On-shade Brackets',kind:'shade',product:'Roller 100',mount:null,code:''},{name:'Roller 100 Mounting Sub-Brackets',kind:'sub',product:'Roller 100',mount:null,code:''},...Object.keys(mounts).flatMap(m=>partEntries(m).map((p,i)=>({...p,product:'Roller 100',mount:m,kind:i===2?'sub':'shade'}))),{name:'Roller 20 Universal Shade Bracket',product:'Roller 20',kind:'shade',mount:null,code:'WIN-BRK-20U'}];
const normalize=q=>q.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function matchingParts(query,filtered=true){const q=normalize(query),tokens=q.split(/ +/).filter(Boolean),compact=q.replace(/ /g,'');return catalog.map((p,index)=>({...p,index})).filter(p=>{
const kinds={'On-shade brackets':'shade','Mounting sub-brackets':'sub','Endcaps':'endcap','Drives':'drive','Coupled shade components':'coupled'};
const families=filterValues('family'),products=filterValues('product'),selectedMounts=filterValues('filterMount'),partKinds=filterValues('partType').map(value=>kinds[value]);
if(filtered&&(families.length&&!families.includes(p.family||'Roller Shades')||products.length&&!products.includes(p.product)||selectedMounts.length&&!selectedMounts.includes(p.mount)||partKinds.length&&!partKinds.includes(p.kind)))return false;
const hay=normalize(p.name+' '+p.code+' '+(p.mount||'')+' mounting hardware'),words=hay.split(' '),code=normalize(p.code).replace(/ /g,'');return !q||code.includes(compact)&&!!compact||tokens.every(t=>words.some(w=>w.startsWith(t)||w===t.replace(/s$/,'')));
}).map(p=>({...p,score:!q?0:normalize(p.code).replace(/ /g,'')===compact?100:normalize(p.name)===q?90:p.code&&normalize(p.code).replace(/ /g,'').startsWith(compact)?70:normalize(p.name).startsWith(q)?50:p.mount&&normalize(p.mount).startsWith(q)?40:20})).sort((a,b)=>b.score-a.score||Number(!!a.code)-Number(!!b.code)||a.index-b.index)}
let searchActive=-1;
function suggestions(input){const box=$('#'+input.id+'-suggestions');if(!box)return;searchActive=-1;const q=input.value.trim(),partNumber=input.dataset.partNumber==='true',limit=partNumber?3:8,matches=q?matchingParts(q,input.id==='query').filter(p=>!partNumber||p.code&&normalize(p.code).replace(/ /g,'').includes(normalize(q).replace(/ /g,''))):[];box.hidden=!q;input.setAttribute('aria-expanded',String(!!q));input.removeAttribute('aria-activedescendant');box.innerHTML=q?`<div class="suggestion-heading">${matches.length?'Suggested matches':'No matching parts'}</div><div role="listbox" id="${input.id}-options" aria-label="Suggested parts">${matches.slice(0,limit).map((p,i)=>`<button type="button" role="option" aria-selected="false" id="${input.id}-option-${i}" data-action="search-pick" data-index="${p.index}" class="suggestion"><strong>${productPill(p.name)}</strong><span>${p.code?`<b class="partcode">${p.code}</b>`:'Product category · Choose a mounting condition'}</span></button>`).join('')}</div>${matches.length>limit?'<p class="meta suggestion-hint">Keep typing to narrow these matches.</p>':''}${!matches.length?`<p class="meta suggestion-hint">${partNumber?'Check the number or try fewer characters.':'Try another product name, mount type, or part number.'}</p>`:''}${reference('SEARCH-'+(input.id==='query'?'DIRECTORY':'ENTRY')+'-SUGGESTIONS')}`:'';input.setAttribute('aria-controls',input.id+'-options')}
function closeSuggestions(){document.querySelectorAll('.search-suggestions').forEach(x=>x.hidden=true);document.querySelectorAll('[role="combobox"]').forEach(x=>{x.setAttribute('aria-expanded','false');x.removeAttribute('aria-activedescendant')});searchActive=-1}
function hasSearch(){return !!state.query.trim()||Object.keys(directoryFilters).some(field=>filterValues(field).length)}
function directoryResults(){if(!hasSearch())return `<div class="panel empty directory-empty">${icon('Search')}<h2>Find the part you need</h2><p class="small-gap">Search by product name, mount type, or part number.<br>Or choose a product or part type using the filters.</p><div class="row wrap small-gap" style="justify-content:center">${btn('Roller 100','search-tag','tag','data-value="Roller 100"')}${btn('On-shade brackets','search-tag','tag part-type-tag','data-value="On-shade brackets"')}</div></div>`;
const matches=matchingParts(state.query),r100=matches.filter(p=>p.product==='Roller 100'),namedMounts=[...new Set(r100.filter(p=>p.mount).map(p=>p.mount))];if(!state.mount)state.mount=filterValues('filterMount').length===1?filterValues('filterMount')[0]:namedMounts.length===1?namedMounts[0]:null;
const exact=matches.filter(p=>p.code&&normalize(p.code).replace(/ /g,'')===normalize(state.query).replace(/ /g,''));let cards=exact.length?`<div class="context"><b>Exact part-number match</b><span>${exact[0].code}</span>${exact.map(p=>btn(p.mount?p.mount+' mount':'View part','search-pick','small',`data-index="${p.index}"`)).join('')}</div>`:'';
if(r100.some(p=>p.kind==='shade'))cards+=productCard();if(r100.some(p=>p.kind==='sub'))cards+=subCard();if(matches.some(p=>p.product==='Roller 20'))cards+=roller20();return cards||`<div class="panel empty"><h2>No matching parts</h2><p class="small-gap">Try a different search or clear the filters.</p><div class="row wrap small-gap" style="justify-content:center">${btn('Clear search and filters','clear-filters')}${btn('Launch Part Pilot','assistant','link')}</div></div>`}
function updateDirectoryResults(){rememberView();const results=$('#directory-results');if(results){results.innerHTML=directoryResults();stampFeatures();const ref=$('#page-reference');if(ref)ref.innerHTML=referenceContent(pageReference());const back=$('.page-utilities .go-back-button');if(back)back.disabled=!viewHistory.length}}
function productCard(){const m=state.mount,d=mounts[m];return `<article class="panel product on-shade-card">${productPill('ROLLER 100','product-card-system')}<div class="bracket-card-heading"><h2 class="product-title-line">${productTitle('On-shade Brackets',m)}</h2><div class="bracket-card-actions">${btn(state.expanded?'Show less detail':'Show More Detail','expand',state.expanded?'pink':'detail')}${btn(d?'Add':'Select Mount','card-add','primary')}</div></div>${d?`<div class="partstrip">${[['Left shade bracket',d.left],['Right shade bracket',d.right]].map(([n,c])=>`<div><small>${n}</small><div class="row small-gap"><span class="partcode">${c}</span>${copy(c)}</div></div>`).join('')}</div>`:''}<div class="card-actions product-card-context">${d?btn('Change mount type','mount-menu'):'<div class="general-part-number"><span>Part number</span><strong>Mixed</strong></div>'}</div><div class="facts on-shade-facts"><div class="fact"><span>Product category</span>Roller Shades</div><div class="fact"><span>Part category</span>Mounting Hardware</div><div class="fact"><span>Dimensions/Specs</span>${btn('See Detail Drawing','drawing','link detail')}</div><div class="fact"><span>Sub-bracket required</span>${btn(d?d.sub:'Select mount','sub-detail','link',d?`data-mount="${m}"`:'')}</div></div>${state.expanded?accordions():''}</article>`}
function accordions(){return `<div class="accordions">${accordion('Product Details',`<div class="placeholder-tag">Illustrative overview copy</div><p>This bracket attaches directly to the shade tube. A compatible mounting sub-bracket is required for installation. Select a mount type to see the associated parts.</p><div class="info-box"><p><b>Product:</b> ${productPill('Roller 100')}<br><b>Mount types:</b> Ceiling · Fascia · Pocket · Wall · Jamb<br><b>Part numbers by mount:</b> ${link('See all','mount-menu')}</p></div>`)}${accordion("What’s Included",`<div class="placeholder-tag">Illustrative explanatory copy</div><p>Left and right on-shade brackets are listed individually. The mounting sub-bracket is a separate line item. A complete bracket selection adds all three part numbers as separate lines.</p>`)}${accordion('FAQs',`<div class="placeholder-tag">Illustrative FAQ copy</div><div class="faq"><strong>How does the on-shade bracket connect to the mounting surface?</strong><p>A mounting sub-bracket connects the shade bracket to the mounting surface. ${link('Select Mount','mount-menu')}</p></div><div class="faq"><strong>Can I request just one side?</strong><p>Choose Add, then Partial when prompted, and select Left, Right, or Both.</p></div><div class="faq"><strong>What if the customer is not sure which bracket they need?</strong><p>${link('Launch Part Pilot','assistant')} to work through the identification questions.</p></div>`)}${accordion('Resources',resources())}${accordion('Related Products',`<div class="placeholder-tag">Illustrative related-product examples</div>${[['Roller 100 Multi-Panel In-Line Coupled Bracket Kit','Configure a complete coupled-system kit.'],['Roller 100 Coupled Sub-Bracket','Mounting hardware at a coupled-shade connection.'],['Roller 100 In-Line Shade Coupler','Choose the mounting type and drive side.']].map(([h,p])=>`<div class="related"><div><b>${productPill(h)}</b><p class="meta">${p}</p></div>${btn('Quick Add','related','small',`data-name="${h}"`)}</div>`).join('')}`)}</div><div class="pills"><span class="neutral-tag">ON-SHADE</span><span class="neutral-tag">BRACKET</span><span class="neutral-tag">SIVOIA QS</span>${state.mount?`<span class="neutral-tag">${state.mount.toUpperCase()} MOUNT</span>`:''}</div>`}
function accordion(name,body){return `<details class="accordion"><summary>${name}</summary><div class="accordion-content">${body}</div></details>`}
function resources(){return `<details class="resource"><summary>Detail Drawings</summary>${Object.keys(mounts).map(m=>`<details class="resource"><summary>${m} Mount</summary><ul>${['Left bracket','Right bracket',...(m==='Fascia'?['3 in square fascia','4 in square fascia and cap']:[])].map(v=>`<li>${btn(v,'asset','link detail',`data-mount="${m}" data-variant="${v}"`)}</li>`).join('')}</ul></details>`).join('')}<details class="resource"><summary>Other components</summary>${btn('Fascia bracket','resource-asset','link detail','data-name="Fascia bracket drawing"')}<br>${btn('5 in top back cover','resource-asset','link detail','data-name="5 in top back cover drawing"')}</details></details>${['Mounting & Configuration Views','Installation Guides','Product Specifications','CAD & Downloads'].map(n=>`<details class="resource"><summary>${n}</summary>${btn('Open '+n.toLowerCase(),'resource-asset','link detail',`data-name="${n}"`)}</details>`).join('')}<p class="meta small-gap">Looking for more Roller 100 specs? ${btn('Open Lutron Support','support','link detail')}</p>`}
function subCard(){return `<article class="panel product sub-bracket-card">${productPill('ROLLER 100','product-card-system')}<div class="bracket-card-heading"><h2>${productPill('Mounting Sub-Brackets','product-title-pill')}</h2><div class="bracket-card-actions sub-bracket-actions">${btn('Show More Detail','sub-more-detail','sub-more-detail')}${btn('Select Mount','sub-quick-add','primary')}</div></div><p class="sub-bracket-headline">Select the desired mounting condition to get started.</p></article>`}
function showSubBracketDetails(){openModal(modalFrame('Mounting Sub-Brackets',`<article class="sub-bracket-detail">${productPill('ROLLER 100','product-card-system')}<p class="small-gap">Mounting sub-brackets connect the on-shade brackets to the mounting surface.</p><div class="tablewrap small-gap"><table><thead><tr><th>Mounting condition</th><th>Part number</th><th>Resources &amp; actions</th></tr></thead><tbody>${Object.entries(mounts).map(([mount,data])=>`<tr><td>${mount} mount</td><td><div class="row wrap"><b class="partcode">${data.sub}</b>${copy(data.sub)}</div></td><td><div class="sub-row-actions">${btn('See Detail Drawing','asset','link detail',`data-mount="${mount}" data-variant="Mounting detail"`)}${btn('See Details','sub-detail','sub-row-details',`data-mount="${mount}"`)}${btn('Quick Add','sub-row-add','primary',`data-mount="${mount}"`)}</div></td></tr>`).join('')}</tbody></table></div><p class="sub-add-status" role="status" aria-live="polite" hidden></p><section class="bracket-kit-banner"><div><h3>Need a complete bracket kit?</h3><p>Get started building your bracket bundle.</p></div>${btn('Launch Bracket Calculator &gt;','bracket-calculator','primary')}</section><p class="meta small-gap">On-shade brackets are separate parts. Choose your mounting condition, then select the bracket coverage you need.</p></article>`,'M-ROLLER100-SUB-BRACKETS-DETAILS'))}
function roller20(){return `<article class="panel product">${productPill('ROLLER 20','product-card-system')}<h2>${productPill('Universal Shade Bracket','product-title-pill')}</h2><div class="partstrip"><div><small>Part number</small><div class="row small-gap"><span class="partcode">WIN-BRK-20U</span>${copy('WIN-BRK-20U')}</div></div><div><small>Ordering unit</small><p>1 pair</p></div></div><div class="card-actions">${btn('View details','r20detail','link detail')}${btn('Add pair','r20add','primary')}</div></article>`}
function directory(){return `<main class="page directory-page">${crumbs('Parts directory')}${title('Parts directory','Choose a product or search for a part.',btn(icon('CircleHelp')+'<span>Not sure? Launch Part Pilot</span>','assistant','assistant-trigger'))}<div class="workspace">${filters()}<section>${searchBar()}<div class="activefilters">${activeFilterTags()}</div><div id="directory-results" aria-live="polite">${directoryResults()}</div></section>${cart()}</div></main>`}
function upload(){return `<main class="page">${crumbs('Upload quote')}<section class="panel uploadpanel">${title('Start with a quote','Choose the quote containing the shade you need parts for.')}<div class="dropzone" id="dropzone"><div class="empty-icon">${icon('Upload')}</div><h2>Drop your quote PDF here</h2><p>Or choose a file from your computer.</p><input type="file" id="quote-file" accept=".pdf" class="sr-only">${btn('Choose PDF','choose-file','primary')}<p class="meta">Prototype only · The file is not uploaded or read.</p></div><div class="row between wrap"><p>Explore the workflow with a sample quote.</p>${btn('Use sample quote','sample-quote')}</div><div class="footer-actions">${btn('Back','entry')}</div></section></main>`}
function processing(){return `<main class="page"><section class="panel completion"><h1>Reading your quote</h1><p>${esc(state.quoteName)}</p><div class="progress"><span></span></div><p class="meta">Simulating quote processing using illustrative data.</p></section></main>`}
function selectedLineControl(){return state.selectedLines.length>1?btn('Switch line · '+state.selectedLines.length+' selected','selected-lines-menu','small selected-lines-trigger','aria-haspopup="dialog"'):link('Choose another line','lines')}
function lines(){const count=state.selectedLines.length,all=count===quoteLines.length;return `<main class="page quote-lines-page">${crumbs('Quote lines')}${title('Quote ID 4593391.4','Select all lines that need replacement components.')}<div class="context"><b class="row">${icon('FileText')} ${esc(state.quoteName)}</b><span>Illustrative quote data</span>${link('Choose another quote','upload')}</div><section class="panel quote-lines-panel"><div class="row between wrap"><h2>Shades in this quote</h2><div class="quote-list-tools"><span class="quote-line-count">${quoteLines.length} quote lines</span><label class="quote-select-all"><input type="checkbox" id="select-all-lines" ${all?'checked':''}><span>Select all</span></label></div></div><div class="tablewrap quote-line-table small-gap"><table><thead><tr><th scope="col">Line</th><th scope="col">Area / shade</th><th scope="col">Product</th><th scope="col">Communication</th><th scope="col">Mounting</th><th scope="col">Drive Side</th><th scope="col" class="line-select-cell">Select</th></tr></thead><tbody>${quoteLines.map(line=>`<tr data-quote-line="${line.id}" class="${state.selectedLines.includes(line.id)?'selected':''}"><td class="line-number">${String(line.id).padStart(2,'0')}</td><td class="line-area">${esc(line.area)}</td><td>${productPill(line.product,'quote-product-tag')}</td><td><span class="quote-communication-tag">${esc(line.communication)}</span></td><td>${esc(line.mount)} mount</td><td class="quote-drive-side">${esc(line.driveSide)}</td><td class="line-select-cell"><label class="line-check-target"><input type="checkbox" name="line" aria-label="Select line ${line.id}: ${esc(line.area)}, ${esc(line.product)}, ${esc(line.mount)} mount" value="${line.id}" ${state.selectedLines.includes(line.id)?'checked':''}></label></td></tr>`).join('')}</tbody></table></div><div class="quote-selection-summary" aria-live="polite">${count?`<span class="selection-mark">${icon('Check')}</span><span><b>${count} of ${quoteLines.length} lines selected</b><span>Choose replacement components for each selected line.</span></span>`:'<span>Select one or more lines to continue.</span>'}</div></section><div class="footer-actions">${btn('Back','upload')}${btn('Find replacement parts','components','primary',count?'':'disabled')}</div></main>`}
function quoteContext(){const line=selectedQuoteLine();if(!line)return '';return `<div class="context"><b>Line ${line.id} · ${esc(line.area)}</b>${productPill(line.product)}${selectedLineControl()}</div>`}
const componentCategories=[{key:'brackets',icon:'Box',name:'Brackets',description:'On-shade brackets and mounting sub-brackets.'},{key:'endcaps',icon:'Square',name:'Endcaps',description:'Covers for the shade tube ends.'},{key:'drive',icon:'Zap',name:'Drive',description:'Components that operate the shade.'},{key:'tube-fabric',icon:'Layers',name:'Tube & Fabric',description:'The shade tube and fabric.'}];
const componentView={selectionKey:null,openLines:new Set(),openDetails:new Set()};
function componentBracketFacts(line){const mount=mounts[line.mount];return `<div class="bracket-facts-scroll"><div class="component-part-facts bracket-part-facts">${[['Left shade bracket',mount.left],['Right shade bracket',mount.right],['Sub-bracket required',mount.sub]].map(([label,code],index)=>`<div class="component-part-fact ${index===2?'sub-bracket-fact':'shade-bracket-fact'}"><span>${label}</span><div class="row"><b class="partcode">${code}</b>${copy(code)}</div></div>`).join('')}</div></div>`}
function componentQuickActions(line,category){return `<div class="component-quick-actions">${btn('Show More Detail','component-more-detail','component-more-detail',`data-line-id="${line.id}" data-component="${category.key}"`)}${btn('Hide','component-hide','pink component-hide',`data-component-key="${line.id}-${category.key}"`)}</div>`}
function componentKnownFacts(line,category){if(category.key==='brackets'&&line.product==='Roller 100')return componentBracketFacts(line);return `<div class="component-part-facts"><div class="component-part-fact"><span>Product</span><b>${esc(line.product)}</b></div><div class="component-part-fact"><span>Mounting condition</span><b>${esc(line.mount)} mount</b></div><div class="component-part-fact"><span>Part numbers</span><p class="meta">Not included for this component in the prototype.</p></div></div>`}
function componentProductPreview(line,category){const bracket=category.key==='brackets'&&line.product==='Roller 100';return `<article class="panel component-inline-product component-quick-facts"><div class="component-quick-heading"><h2 class="product-title-line">${productTitle(bracket?'On-shade Brackets':category.name,line.mount,false)}</h2>${bracket?btn('See Detail Drawing','component-inline-drawing','link detail',`data-line-id="${line.id}"`):''}</div>${componentKnownFacts(line,category)}${componentQuickActions(line,category)}${reference('P06-COMPONENTS-LINE-'+line.id+'-'+slug(category.key)+'-DETAILS')}</article>`}
function openComponentProductDetails(line,category=componentCategories[0]){const bracket=category.key==='brackets'&&line.product==='Roller 100';state.line=line.id;state.mount=line.mount;sourceQuote();openModal(modalFrame(bracket?'On-shade Brackets':category.name,`<article class="component-product-modal">${productPill(line.product,'product-card-system')}<p class="meta small-gap">Line ${line.id} · ${esc(line.area)} · ${esc(line.mount)} mount</p>${componentKnownFacts(line,category)}${bracket?`<div class="row wrap component-modal-actions">${btn('See Detail Drawing','component-inline-drawing','link detail',`data-line-id="${line.id}"`)}</div>${accordions()}`:`<div class="accordions">${accordion('Product Details',`<p>${category.description}</p><p class="meta small-gap">Detailed product specifications and resources are not included for this component in the prototype.</p>`)}</div>`}</article>`,'P06-COMPONENTS-LINE-'+line.id+'-'+slug(category.key)+'-FULL-DETAILS',line.mount))}
function components(){const selected=quoteLines.filter(line=>state.selectedLines.includes(line.id)),selectionKey=selected.map(line=>line.id).join(',');if(componentView.selectionKey!==selectionKey){componentView.selectionKey=selectionKey;componentView.openLines=new Set();componentView.openDetails.clear()}return `<main class="page components-page">${crumbs('Replacement parts')}${title('Choose a component','Select the part of the shade you need to replace.')}<div class="workspace two"><section class="component-line-list">${selected.map(line=>`<details class="panel component-line-accordion" data-component-line="${line.id}" ${componentView.openLines.has(line.id)?'open':''}><summary class="component-line-summary"><div class="component-line-identity"><h2>${esc(line.area)}</h2><div class="component-line-meta"><span class="component-line-number">Line ${line.id}</span><span class="component-line-meta-divider" aria-hidden="true">·</span>${productPill(line.product,'component-product-tag')}</div></div><span class="component-line-count">4 components</span><span class="line-accordion-chevron">${icon('ChevronDown')}</span></summary><div class="component-list">${componentCategories.map(category=>{const key=line.id+'-'+category.key,open=componentView.openDetails.has(key),panelId='component-detail-'+key;return `<section class="component-entry ${open?'detail-open':''}" data-component-key="${key}"><div class="component"><span class="mini-icon">${icon(category.icon)}</span><div class="component-description"><div class="component-heading">${productPill(line.product,'component-product-tag')}<h3>${category.name}</h3><p class="component-inline-description"><span aria-hidden="true">— </span>${category.description}</p></div></div><div class="row component-actions">${btn(open?'Hide details':'Details','component-toggle','link detail',`data-component-key="${key}" aria-expanded="${open}" aria-controls="${panelId}"`)}${btn('Replace','component-replace','primary',`data-line-id="${line.id}" data-component="${category.key}" data-name="${category.name}"`)}</div></div><div id="${panelId}" class="component-detail-panel" ${open?'':'hidden'}>${componentProductPreview(line,category)}</div></section>`}).join('')}</div></details>`).join('')}<div class="footer-actions">${btn('Back','lines')}${link('Edit selected lines','lines')}</div></section>${cart()}</div></main>`}
function method(){return `<main class="page">${crumbs('Replacement method')}${quoteContext()}<div class="workspace two"><section class="panel">${title('How would you like to replace these?','Keep the original mounting condition or choose another.')}<div class="choices">${btn(`<span class="choice-icon">${icon('Package')}</span><h3>As ordered</h3><p>Keep the original ${esc(selectedQuoteLine()?.mount.toLowerCase()||'ceiling')} mount.</p>`,'as-ordered','choice')}${btn(`<span class="choice-icon">${icon('SlidersHorizontal')}</span><h3>Change configuration</h3><p>Explore another mounting condition.</p>`,'change-config','choice')}</div><div class="footer-actions">${btn('Back','components')}${link('View original part details','original-detail')}</div></section>${cart()}</div></main>`}
function focused(){return `<main class="page">${crumbs('Product details')}${state.source!=='Parts directory'?quoteContext():''}<div class="workspace two"><section>${productCard()}<div class="footer-actions">${btn('Back',state.source==='Parts directory'?'directory':'method')}</div></section>${cart()}</div></main>`}
function showBracketReplacementChoice(){if(!mounts[state.mount])return;openModal(modalFrame('Choose your bracket replacement',`${quoteContext()}<div class="context"><b>${esc(state.mount)} mount</b></div><div class="choices">${btn(`<span class="choice-icon">${icon('Package')}</span><h3>Complete Kit</h3><p>Left and right on-shade brackets plus the mounting sub-bracket kit.</p>`,'replacement-choice-complete','choice')}${btn(`<span class="choice-icon">${icon('SlidersHorizontal')}</span><h3>Partial</h3><p>Choose the brackets you need.</p>`,'replacement-choice-partial','choice')}</div>`,'M-BRACKET-REPLACEMENT-CHOICE-'+slug(state.mount)))}
function bracketSelection(){return `<section class="bracket-selection-modal">${state.source!=='Parts directory'?quoteContext():''}<div class="context"><b>${state.mount} mount</b>${link('Change mounting','coverage-mount')}</div><div class="selection-block"><label class="checkline"><input type="checkbox" data-field="includeShade" ${state.includeShade?'checked':''}>On-shade brackets</label><p>The brackets that attach directly to the shade.</p>${state.includeShade?`<div class="indent shade-side-controls"><h3 class="small-gap">Which side needs replacement?</h3><div class="segment">${['Left','Right','Both'].map(x=>btn(x,'side',state.side===x?'selected':'',`data-side="${x}"`)).join('')}</div>${link('How do I identify left and right?','orientation')}</div>`:''}</div><div class="selection-block"><label class="checkline"><input type="checkbox" data-field="includeSub" ${state.includeSub?'checked':''}>Mounting sub-brackets</label><p>The hardware that connects the shade brackets to the mounting surface.</p><div class="indent small-gap"><span class="partcode">${mounts[state.mount].sub}</span> ${btn('View part details','sub-detail','link detail',`data-mount="${state.mount}"`)}</div></div><div class="footer-actions">${btn('Add selected parts','add-selected','primary',!state.includeShade&&!state.includeSub?'disabled':'')}</div></section>`}
function showBracketSelection(refresh=false){if(!mounts[state.mount]){openMountMenu('coverage');return}if(!refresh)render();const scroll=$('#modal').scrollTop;openModal(modalFrame('Choose the brackets you need',bracketSelection(),'P09-BRACKET-SELECTION-'+slug(state.mount)),refresh);$('#modal').scrollTop=refresh?scroll:0}
function bracketSelectionSnapshot(){return $('#modal .bracket-selection-modal')?{mount:state.mount,includeShade:state.includeShade,includeSub:state.includeSub,side:state.side,selectionOrigin:state.selectionOrigin,source:state.source}:null}
function review(){return `<main class="page">${crumbs('Review parts')}${title('Review your parts','Check part numbers and quantities before exporting.')}<section class="panel">${state.cart.length?`<p>${state.cart.length} part numbers</p><div class="tablewrap small-gap"><table><thead><tr><th>Part</th><th>Source</th><th>Quantity</th><th></th></tr></thead><tbody>${state.cart.map((x,i)=>`<tr><td><div class="reviewname">${productPill(x.name)}</div><span class="partcode">${x.code}</span> ${copy(x.code)}</td><td><span class="meta">${esc(x.sources.join(' · '))}</span></td><td><div class="row"><div class="qty">${btn('−','qty','','data-index="'+i+'" data-delta="-1"')}<input aria-label="Quantity of ${x.code}" type="number" min="1" max="999" data-qty="${i}" value="${x.qty}">${btn('+','qty','','data-index="'+i+'" data-delta="1"')}</div><span class="meta">${x.unit}</span></div></td><td>${link('Remove','remove',`data-index="${i}"`)}</td></tr>`).join('')}</tbody></table></div><p class="meta small-gap">Repeated part numbers are combined. A bundle adds its component part numbers as separate lines.</p>`:`<div class="empty"><h2 class="empty-list-heading">Start adding parts</h2><p>Add parts from a quote or the directory.</p></div>`}</section><div class="footer-actions"><p class="meta">Export creates a CSV; it does not place an order.</p><div class="row wrap">${btn('Add more parts','directory')}${btn('Export parts CSV','export','primary',!state.cart.length?'disabled':'')}</div></div></main>`}
function complete(){return `<main class="page">${crumbs('Export complete')}<section class="panel completion"><div class="success">${icon('Check')}</div><h1>Your parts list is ready</h1><p>${state.cart.length} part numbers prepared for export.</p><div class="info-box"><b>Particle_replacement_parts.csv</b><p class="meta">Prototype preview · No file was generated or order placed.</p></div><div class="row wrap small-gap" style="justify-content:center">${btn('View export preview','export-preview','primary')}${btn('Back to parts list','review')}${btn('Find more parts','directory','link')}</div></section></main>`}
function builder(){const names=['Drapery','Roller Shades','Wood Blinds','Roman Shades','Honeycomb Shades'],pos=[[645,182],[967,182],[484,520],[806,520],[1128,520]];return `<main class="page">${crumbs('Shade Builder')}${title('What kind of shade are we building?','Select a product to begin.')}<p class="meta">Lutron Shade Builder v2.0 (Beta)</p><div class="builder-grid">${names.map((n,i)=>btn(`<span class="shade-art"><img src="shade-reference.png" alt="${n}" style="left:-${pos[i][0]/3}%;top:-${pos[i][1]/2.9}%"></span><strong>${productPill(n)}</strong>`,'shade','shade-choice '+(state.shade===n?'selected':''),`data-name="${n}"`)).join('')}</div><div class="footer-actions">${btn('Back','home')}${btn('Continue with '+state.shade,'builder-next','primary')}</div><p class="meta small-gap">Introductory workflow preview</p></main>`}
function csr(){return `<main class="page csr-page">${crumbs('CSR Automate')}<section class="portal">${title('CSR Automate','Customer Shading Request')}<div class="steps"><span><b>1</b>Find project</span><span><b>2</b>Select revision</span><span><b>3</b>Choose lines</span><span><b>4</b>Add details</span><span><b>5</b>Submit to CSR</span></div><form class="panel" id="csr-form"><h2>Start your custom shading request</h2><p class="small-gap">Enter your myProjects Project ID then select the revision and lines requiring engineering review.</p><label class="label" for="project-id">Project ID</label><div class="row"><input id="project-id" placeholder="Enter Project ID" required><button class="primary" type="submit">Find project</button></div><p class="engineering-chat-prompt">Have a configuration question? ${btn('Chat with Engineering','engineering-chat','link engineering-chat-link')}</p></form><div class="footer-actions">${btn('Back','home')}</div><p class="meta csr-demo-notice">Demonstration only · No project connection or submission</p></section></main>`}
const assistantQs=[{q:'What kind of product does the customer have?',hint:'Ask: “Are these roller shades or another type of window treatment?”',answers:['Roller shades','Another product','Not sure']},{q:'Which roller shade product is it?',hint:'Ask whether the product name is on the order information or product label.',answers:['Roller 100','Another roller product','Not sure']},{q:'What is the mounting condition?',hint:'Ask the customer to describe where the shade will be installed.',answers:['Ceiling','Fascia','Pocket','Wall','Jamb','Not sure']},{q:'Are brackets already attached to the shade tube?',hint:'Ask the customer to look at both ends of the shade tube.',answers:['Yes, both ends','One end only','No brackets attached','Not sure']}];
function assistant(){const a=state.assistant,unknown=a.some(x=>x==='Not sure'||x.startsWith('Another')),needsSize=['Fascia','Pocket'].includes(a[2]),sizePending=needsSize&&a.length===3;let idx=a.length;if(needsSize&&a.length>3)idx--;let question=sizePending?{q:`What size is the ${a[2].toLowerCase()}?`,hint:'Ask for the measured size or label. Keep “Not sure” available if it cannot be confirmed.',answers:['Enter a measurement','Not sure']}:assistantQs[idx];if(unknown)question=null;return `<main class="page">${crumbs('Part Pilot')}<section class="panel assistant-panel"><div class="row between"><h2 class="part-pilot-title">Part <span>Pilot</span></h2>${link('Start over','assistant-reset')}</div><div class="answer-history">${a.map((x,i)=>btn((['Roller 100','Roller shades'].includes(x)?productPill(x):esc(x))+' ×','edit-answer','',`data-index="${i}"`)).join('')}</div>${question?`<p class="meta">Ask the customer</p><h1 class="question">${question.q}</h1><p>${question.hint}</p><div class="answers small-gap">${question.answers.map(x=>btn(['Roller 100','Roller shades'].includes(x)?productPill(x):x,'answer','',`data-answer="${x}"`)).join('')}</div>`:unknown?`<h1 class="question">Let’s confirm what they have</h1><p>A photo can help distinguish the hardware without guessing.</p><div class="info-box"><h3>Ask for these views</h3><p>Both ends of the shade tube, the loose brackets received, and the intended mounting area. Include the fascia or pocket and a readable size measurement where relevant.</p></div><div class="note">Identification is unresolved. Photos in this concept are reviewed by a person; automated recognition is not assumed.</div>${btn('Copy photo request','copy-photo','primary','style="margin-top:22px"')}`:`<h1 class="question">Review the ${esc(a[2])} mount candidates</h1><p>Your answers give us a starting point. Compare the customer’s hardware with the official drawing before confirming the part.</p><div class="info-box"><h3>${productPill('Roller 100')} · ${esc(a[2])} mount</h3><p>${esc(a[a.length-1])}</p></div><div class="note">Guided concept only · These answers do not establish a verified match.</div><div class="row wrap small-gap">${btn('View candidate parts','assistant-result','primary')}${btn('Request a photo','request-photo')}</div>`}<div class="footer-actions">${btn(a.length?'Previous question':'Back to parts',a.length?'assistant-back':'entry')}</div></section></main>`}
const screenRefs={login:'P01-LOGIN',home:'P02-HOME',entry:'P03-FIND-PART',directory:'P11-DIRECTORY',upload:'P04-UPLOAD',processing:'P04-PROCESSING',lines:'P05-QUOTE-LINES',components:'P06-COMPONENTS',method:'P07-REPLACEMENT-METHOD',focused:'P08-PRODUCT',selection:'P09-BRACKET-SELECTION',review:'P10-REVIEW',complete:'P12-EXPORT',builder:'P20-SHADE-BUILDER',csr:'P21-CSR-AUTOMATE',assistant:'P22-PART-ASSISTANT'};
const slug=s=>String(s).toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-|-$/g,'');
function pageReference(){let id=screenRefs[state.page]||slug(state.page);if(['focused','selection','directory'].includes(state.page))id+='-'+(state.page==='directory'&&!hasSearch()?'EMPTY':slug(state.mount||'GENERAL'))+(state.expanded?'-EXPANDED':'');if(state.page==='directory'&&hasSearch()){const matches=matchingParts(state.query);if(!matches.length)id+='-NO-MATCHES';else if(matches.every(p=>p.product==='Roller 20'))id+='-ROLLER20';else if(matches.every(p=>p.kind==='sub'))id+='-SUB-BRACKETS'}if(state.page==='assistant'){const a=state.assistant,unknown=a.some(x=>x==='Not sure'||x.startsWith('Another')),size=['Fascia','Pocket'].includes(a[2]);id+='-'+(unknown?'PHOTO-REQUEST':size&&a.length===3?'TOP-TREATMENT-SIZE':a.length>=(size?5:4)?'CANDIDATES-'+slug(a[2]):['PRODUCT-TYPE','PRODUCT-FAMILY','MOUNT-TYPE','ATTACHED-BRACKETS'][size&&a.length>3?a.length-1:a.length])}if(state.page==='builder')id+='-'+slug(state.shade);return id}
function reference(id,cls='feature-reference'){return `<div class="${cls}" aria-label="Reference ID">${referenceContent(id)}</div>`}
function stampDetailReferences(root,prefix){root.querySelectorAll('details').forEach(el=>{let path=[],p=el;while(p&&p.tagName==='DETAILS'&&root.contains(p)){path.unshift(p.querySelector(':scope > summary')?.textContent||'DETAIL');p=p.parentElement?.closest('details')}const id=prefix+'-'+path.map(slug).join('-'),existing=el.querySelector(':scope > .feature-reference');if(existing)existing.innerHTML=referenceContent(id);else el.insertAdjacentHTML('beforeend',reference(id))})}
function stampFeatures(){stampDetailReferences($('#app'),pageReference());for(const [selector,suffix] of [['.filters','FILTERS'],['.cart','REPLACEMENT-LIST']]){const el=$(selector);if(el){const id=pageReference()+'-'+suffix,existing=el.querySelector(':scope > .feature-reference');if(existing)existing.innerHTML=referenceContent(id);else el.insertAdjacentHTML('beforeend',reference(id))}}}
function render(){rememberView();document.body.dataset.screen=state.page;const views={login,home,entry,directory,upload,processing,lines,components,method,focused,selection:bracketSelection,review,complete,builder,csr,assistant};$('#app').innerHTML=(state.page==='login'?'':header())+(views[state.page]||home)()+`<div class="page-utilities">${backControl()}<div id="page-reference" class="page-reference">${referenceContent(pageReference())}</div></div>${sessionEndControl()}`;stampFeatures();const selectAll=$('#select-all-lines');if(selectAll)selectAll.indeterminate=state.selectedLines.length>0&&state.selectedLines.length<quoteLines.length;document.title=`Particle | ${({directory:'Parts directory',focused:'Product details',assistant:'Part Pilot',csr:'CSR Automate',builder:'Shade Builder'})[state.page]||'Part Replace'}`}
let menuState={mode:'select',expanded:null,selected:null};
function openModal(body,replace=false){const modal=$('#modal');if(modal.open){if(!replace)modalHistory.push({html:modal.innerHTML,menu:structuredClone(currentModalState?.menu||menuState),scroll:modal.scrollTop,coverage:bracketSelectionSnapshot()})}else modalHistory=[];currentModalState={menu:structuredClone(menuState)};modal.innerHTML=body;stampDetailReferences(modal,modal.querySelector('.modal-reference [data-copy-reference]')?.dataset.copyReference||'M-DETAILS');if(!modal.open)modal.showModal()}
function modalFrame(title,body,id,mount=null){id=id||'M-'+slug(title);const productDetail=body.includes('class="component-product-modal"')||title==='Roller 20 Universal Shade Bracket'||title==='Mounting Sub-Brackets';return `<div class="modal-top"><h2 id="modal-title" class="${productDetail?'product-title-line':''}">${productDetail?productTitle(title,mount):title}</h2>${btn(icon('X'),'close','modal-close','aria-label="Close window"')}</div>${body}<div class="modal-back-row">${btn(icon('ChevronRight','back-arrow')+'<span>Go Back</span>','go-back','go-back-button')}</div>${reference(id,'modal-reference')}${sessionEndControl()}`}
function openMountMenu(mode='select',expanded=null){menuState={mode,expanded,selected:state.mount};renderMountMenu()}
function mountPart(m,kind){const entry=partEntries(m)[{left:0,right:1,sub:2}[kind]];return `<div class="mount-part"><span>${kind==='sub'?'Mount':kind==='left'?'Left':'Right'}</span><b class="partcode">${entry.code}</b>${copy(entry.code)}${btn('Add','quick-part','small',`data-mount="${m}" data-kind="${kind}"`)}</div>`}
function renderMountMenu(){const s=menuState;openModal(modalFrame(s.mode==='drawing'?'Choose a detail drawing':'Mount type',`${s.mode==='drawing'?'<p class="small-gap">Choose a mounting condition to open its official detail drawing in a separate window.</p>':''}${(state.page==='directory'&&filterValues('filterMount').length&&!['sub','bracket-calculator'].includes(s.mode)?filterValues('filterMount'):Object.keys(mounts)).map(m=>`<div class="mount-row"><div class="mount-heading">${btn(m+' Mount','select-mount',s.selected===m?'selected':'',`data-mount="${m}"`)}${btn(s.expanded===m?'Hide details':'Details','mount-expand','link detail',`data-mount="${m}"`)}</div>${s.expanded===m?`<div class="mount-detail"><section><h3>${productPill('On-shade brackets')}<span class="mount-parts-label">Part numbers</span></h3>${mountPart(m,'left')}${mountPart(m,'right')}</section><section class="info-box"><span class="tag required-tag">Required</span><h3>${productPill('Mounting sub-bracket')}</h3>${mountPart(m,'sub')}</section></div>`:''}</div>`).join('')}`, 'M-MOUNT-'+slug(s.mode)+'-'+slug(s.expanded||'OVERVIEW'))) }
const drawingLinks={Ceiling:'https://assets.lutron.com/a/documents/0109-r100-cmb-v.pdf',Fascia:'https://assets.lutron.com/a/documents/0128-r100-fmb-v.pdf',Pocket:'https://assets.lutron.com/a/documents/0121-r100-pmb-v.pdf',Wall:'https://assets.lutron.com/a/documents/0104-r100-wmb-v.pdf',Jamb:'https://assets.lutron.com/a/documents/0104-r100-wmb-v.pdf'};
function drawing(m,variant){if(!m){openMountMenu('drawing');return}window.open(drawingLinks[m],'_blank','noopener,noreferrer')}
function resourceAsset(name){window.open('drawing.html?'+new URLSearchParams({variant:name}),'_blank','noopener,noreferrer')}
function sourceQuote(){const line=selectedQuoteLine();if(line)state.source=`Quote · Line ${line.id} · ${line.area}`}
function quoteProductPreview(){const line=selectedQuoteLine();if(!line)return;openModal(modalFrame(esc(line.product)+' · Replacement preview',`<p>Line ${line.id} · ${esc(line.area)} · ${esc(line.mount)} mount</p><p class="small-gap">This product is included in the sample quote. The complete replacement workflow in this prototype covers Roller 100 brackets.</p><div class="row wrap small-gap">${btn('Choose another line','lines','primary')}${btn('Parts directory','directory')}</div>`))}
function startQuote(){state.line=null;state.selectedLines=[];navigate('processing');setTimeout(()=>{if(state.page==='processing')navigate('lines')},1450)}
function handle(action,el){switch(action){
case 'go-back':goBack();break;
case 'home':case 'entry':case 'upload':case 'review':case 'lines':case 'builder':case 'csr':case 'focused':navigate(action);break;
case 'method':if(selectedQuoteLine()?.product!=='Roller 100'){quoteProductPreview();break}state.replacementMethod=null;navigate('method');break;
case 'directory':state.source='Parts directory';navigate('directory');break;
case 'part-number-search':openPartNumberSearch();break;
case 'search-tag':if(el.dataset.value==='On-shade brackets')state.partType='On-shade brackets';else state.product=el.dataset.value;render();break;
case 'search-pick':{const p=catalog[Number(el.dataset.index)];if(!p)break;closeSuggestions();state.source='Parts directory';if(state.page!=='directory'){navigate('directory')}resetDirectory();state.query=p.code||p.name;state.mount=p.mount;render();if(p.kind==='sub'&&p.mount)openMountMenu('sub',p.mount);break;}

case 'components':if(!state.selectedLines.length)break;if(!state.selectedLines.includes(state.line))state.line=state.selectedLines[0];state.mount=null;state.expanded=false;sourceQuote();navigate('components');break;
case 'component-toggle':{const key=el.dataset.componentKey,panel=document.getElementById(el.getAttribute('aria-controls')),open=panel.hidden;panel.hidden=!open;el.setAttribute('aria-expanded',String(open));el.textContent=open?'Hide details':'Details';el.closest('.component-entry').classList.toggle('detail-open',open);if(open)componentView.openDetails.add(key);else componentView.openDetails.delete(key);syncCurrentView();break;}
case 'component-hide':{const key=el.dataset.componentKey,toggle=document.querySelector(`.component-entry[data-component-key="${key}"] [data-action="component-toggle"]`);if(toggle){toggle.click();toggle.focus()}break;}
case 'component-more-detail':{const line=quoteLines.find(line=>line.id===Number(el.dataset.lineId));const category=componentCategories.find(category=>category.key===el.dataset.component);if(line&&category)openComponentProductDetails(line,category);break;}
case 'component-replace':{const line=quoteLines.find(line=>line.id===Number(el.dataset.lineId));if(!line||!state.selectedLines.includes(line.id))break;state.line=line.id;state.mount=null;state.expanded=false;sourceQuote();handle(el.dataset.component==='brackets'?'method':'demo-component',el);break;}
case 'component-inline-drawing':{const line=quoteLines.find(line=>line.id===Number(el.dataset.lineId));if(line?.product==='Roller 100')drawing(line.mount);break;}
case 'selected-lines-menu':openModal(modalFrame('Selected quote lines',`<p>Choose the line you want to work on.</p><div class="selected-line-menu small-gap">${quoteLines.filter(line=>state.selectedLines.includes(line.id)).map(line=>btn(`<span class="selected-line-heading"><b>Line ${line.id} · ${esc(line.area)}</b>${line.id===state.line?'<span class="current-line-label">Current line</span>':''}</span><span class="selected-line-detail">${productPill(line.product)}<span>${esc(line.mount)} mount</span></span>`,'quote-line-pick','selected-line-option'+(line.id===state.line?' current':''),`data-line-id="${line.id}" ${line.id===state.line?'aria-current="true"':''}`)).join('')}</div><div class="small-gap">${btn('Edit selected lines','lines','small')}</div>`,'M-QUOTE-SELECTED-LINES'));break;
case 'quote-line-pick':{const id=Number(el.dataset.lineId);if(!state.selectedLines.includes(id))break;state.line=id;state.mount=null;state.expanded=false;sourceQuote();navigate('components');break;}
case 'filter-menu':openDirectoryFilter(el.dataset.filter);break;
case 'filter-pick':{const field=el.dataset.filter,config=directoryFilters[field],value=el.dataset.value;if(!config?.options.includes(value)||filterDraft?.field!==field)break;if(value===config.all)filterDraft.values=[];else filterDraft.values=filterDraft.values.includes(value)?filterDraft.values.filter(x=>x!==value):[...filterDraft.values,value];renderDirectoryFilter(true);$('#modal [data-value="'+CSS.escape(value)+'"]')?.focus({preventScroll:true});break;}
case 'filter-apply':{if(!filterDraft||filterDraft.field!==el.dataset.filter)break;const {field,values}=filterDraft;state[field]=values.length?[...values]:directoryFilters[field].all;state.mount=null;state.expanded=false;$('#modal').close();filterDraft=null;render();document.getElementById(field+'-filter-trigger')?.focus({preventScroll:true});break;}
case 'clear-filter-value':{const field=el.dataset.filter,values=filterValues(field).filter(value=>value!==el.dataset.value);state[field]=values.length?values:directoryFilters[field].all;state.mount=null;state.expanded=false;render();break;}
case 'product-filter-menu':openDirectoryFilter('product');break;
case 'signin-help':openModal(modalFrame('Need help signing in?',`<p>Use your work email to enter your workspace.</p><div class="info-box"><h3>Trying the prototype?</h3><p>You can select Continue without entering an email. No password or email verification is needed.</p></div>${btn('Back to sign in','close','primary','style="margin-top:22px"')}`,'M-LOGIN-HELP'));break;
case 'close':$('#modal').close();break;
case 'help':openModal(modalFrame('How can we help?',`<div class="stack">${btn('<h3>Find a part</h3><p>Search, browse, or start with a quote.</p>','entry','choice')}${btn('<h3>Not sure which bracket?</h3><p>Ask guided questions with Part Pilot.</p>','assistant','choice')}</div><p class="meta small-gap">This prototype simulates the workflows. No orders or requests are sent.</p>`));break;
case 'profile':openModal(modalFrame('Your workspace','<h3>Kenneth</h3><p class="small-gap">Demonstration profile</p>'+btn('Return to sign in','signout','small','style="margin-top:20px"')));break;
case 'signout':navigate('login');break;
case 'mount-menu':openMountMenu();break;
case 'sub-menu':openMountMenu('sub');break;
case 'sub-more-detail':showSubBracketDetails();break;
case 'sub-row-add':{const part=partEntries(el.dataset.mount)[2];addParts([part]);const status=$('#modal .sub-add-status');if(status){status.hidden=false;status.textContent=part.code+' added to your replacement list.'}break;}
case 'bracket-calculator':state.selectionOrigin='bracket-calculator';state.source='Parts directory';openMountMenu('bracket-calculator');break;
case 'sub-quick-add':state.selectionOrigin='sub-quick-add';state.source='Parts directory';openMountMenu('quick-add-sub');break;
case 'coverage-back':goBack();break;
case 'coverage-mount':openMountMenu('coverage');break;
case 'mount-expand':menuState.expanded=menuState.expanded===el.dataset.mount?null:el.dataset.mount;if(menuState.expanded)menuState.selected=menuState.expanded;renderMountMenu();break;
case 'select-mount':if(menuState.mode==='drawing'){drawing(el.dataset.mount);break}state.mount=el.dataset.mount;state.expanded=false;menuState.selected=state.mount;if(menuState.mode==='coverage'){showBracketSelection();break}if(['quick-add-sub','bracket-calculator'].includes(menuState.mode)){state.includeShade=menuState.mode==='bracket-calculator';state.includeSub=true;state.side='Both';state.selectionOrigin=menuState.mode==='bracket-calculator'?'bracket-calculator':'sub-quick-add';navigate('selection')}else{$('#modal').close();render()}break;
case 'menu-bundle':if(menuState.selected){state.mount=menuState.selected;addParts(partEntries(state.mount),state.mount+' bracket bundle');$('#modal').close();render()}break;
case 'focused-bundle':addParts(partEntries(state.mount),state.mount+' bracket bundle');break;
case 'quick-part':addParts([partEntries(el.dataset.mount)[{left:0,right:1,sub:2}[el.dataset.kind]]]);break;
case 'copy':navigator.clipboard?.writeText(el.dataset.code).then(()=>toast('Part number copied')).catch(()=>toast('Copy unavailable in this browser'));break;
case 'expand':state.expanded=!state.expanded;render();break;
case 'card-add':state.selectionOrigin='product';if(!state.mount){openMountMenu();break}if(state.page==='focused'&&state.replacementMethod==='change-config'&&state.source.startsWith('Quote · ')){showBracketReplacementChoice();break}state.includeShade=true;state.includeSub=false;state.side='Both';navigate('selection');break;
case 'drawing':drawing(state.mount,state.mount?'On-shade bracket detail':null);break;
case 'asset':drawing(el.dataset.mount,el.dataset.variant);break;
case 'resource-asset':resourceAsset(el.dataset.name);break;
case 'support':window.open('https://support.lutron.com','_blank','noopener,noreferrer');break;
case 'sub-detail':if(!state.mount&&!el.dataset.mount){openMountMenu('sub');break}openMountMenu('sub',el.dataset.mount||state.mount);break;
case 'clear-filters':state.product='All products';state.family='All type groups';state.partType='All parts';state.filterMount='All mounts';state.color='All colors';state.query='';state.mount=null;state.expanded=false;render();break;
case 'clear-product':state.mount=null;state.product='All products';render();break;
case 'clear-mount':state.mount=null;state.filterMount='All mounts';render();break;
case 'exact':state.mount=el.dataset.mount;navigate('focused');break;
case 'qty':{const x=state.cart[Number(el.dataset.index)];if(x)x.qty=Math.min(999,Math.max(1,x.qty+Number(el.dataset.delta)));renderCart();break}
case 'remove':{const before=structuredClone(state.cart);state.cart.splice(Number(el.dataset.index),1);renderCart();toast('Part removed',()=>{state.cart=before;render();toast('Part restored')});break}
case 'undo':if(toast.undo)toast.undo();break;
case 'r20add':addParts([{code:'WIN-BRK-20U',name:'Roller 20 Universal Shade Bracket',unit:'pair'}]);break;
case 'r20detail':openModal(modalFrame('Roller 20 Universal Shade Bracket',`${productPill('ROLLER 20','product-card-system')}<p class="small-gap">Ordering unit: 1 pair</p><div class="row small-gap"><span class="partcode">WIN-BRK-20U</span>${copy('WIN-BRK-20U')}</div>${btn('Add pair','r20add','primary','style="margin-top:20px"')}`));break;
case 'choose-file':$('#quote-file').click();break;
case 'sample-quote':state.quoteName='Sample quote.pdf';startQuote();break;
case 'as-ordered':state.mount=selectedQuoteLine()?.mount||'Ceiling';state.replacementMethod='as-ordered';sourceQuote();showBracketReplacementChoice();break;
case 'replacement-choice-complete':if(mounts[state.mount]){addParts(partEntries(state.mount),state.mount+' bracket bundle');$('#modal').close();render()}break;
case 'replacement-choice-partial':state.selectionOrigin='replacement-choice';state.includeShade=true;state.includeSub=false;state.side='Both';showBracketSelection();break;
case 'change-config':state.replacementMethod='change-config';state.mount=null;navigate('focused');openMountMenu();break;
case 'original-detail':if(selectedQuoteLine())openComponentProductDetails(selectedQuoteLine());break;
case 'component-detail':if(selectedQuoteLine())openComponentProductDetails(selectedQuoteLine());break;
case 'demo-component':if(selectedQuoteLine()?.product!=='Roller 100'){quoteProductPreview();break}openModal(modalFrame(el.dataset.name||'Component preview','<p>This component is represented in the prototype. The complete interactive example is Roller 100 brackets.</p>'+btn('Explore brackets','method','primary','style="margin-top:20px"')));break;
case 'side':state.side=el.dataset.side;if($('#modal .bracket-selection-modal'))showBracketSelection(true);else render();break;
case 'add-selected':{const entries=partEntries(state.mount);let add=[];if(state.includeShade){if(state.side!=='Right')add.push(entries[0]);if(state.side!=='Left')add.push(entries[1])}if(state.includeSub)add.push(entries[2]);if(add.length){addParts(add);$('#modal').close();render()}break}
case 'orientation':openModal(modalFrame('Identify left and right','<p>Use the official drawing for the selected mounting condition to establish the viewing direction.</p><div class="note">Check the selected mount’s official drawing before confirming left and right. Do not infer orientation from the customer’s position.</div>'+btn('Choose a drawing','drawing','primary','style="margin-top:20px"')));break;
case 'export':navigate('complete');break;
case 'export-preview':openModal(modalFrame('CSV export preview',`<p class="meta">Simulated output · No download or order submission</p><div class="tablewrap small-gap"><table><thead><tr><th>Part number</th><th>Quantity</th><th>Unit</th></tr></thead><tbody>${state.cart.map(x=>`<tr><td>${x.code}</td><td>${x.qty}</td><td>${x.unit}</td></tr>`).join('')}</tbody></table></div>`));break;
case 'shade':state.shade=el.dataset.name;render();break;
case 'builder-next':openModal(modalFrame(state.shade+' · Shade Builder',`<p>This is the starting point for configuring ${esc(state.shade.toLowerCase())}. The detailed configuration workflow is outside this Part Replace demonstration.</p>`));break;
case 'related':openModal(modalFrame(el.dataset.name,`<p>This related-product entry demonstrates the quick-add pathway. Configuration and part-number data are needed before it can be added.</p><p class="meta small-gap">Related product content is illustrative.</p>`));break;
case 'assistant':navigate('assistant');break;
case 'assistant-reset':state.assistant=[];render();break;
case 'assistant-back':state.assistant.pop();render();break;
case 'edit-answer':state.assistant=state.assistant.slice(0,Number(el.dataset.index));render();break;
case 'answer':if(el.dataset.answer==='Enter a measurement'){openModal(modalFrame('Top-treatment size',`<form id="size-form"><label class="label" for="size">Size and units</label><input id="size" placeholder="For example, the measured fascia height" required><button class="primary small-gap" type="submit">Keep measurement</button></form>`))}else{state.assistant.push(el.dataset.answer);render()}break;
case 'request-photo':state.assistant.push('Not sure');render();break;
case 'copy-photo':navigator.clipboard?.writeText('Please send clear photos of both ends of the shade tube, the loose brackets you received, and the intended mounting area. Include any fascia or pocket and a readable size measurement if possible.').then(()=>toast('Photo request copied')).catch(()=>toast('Copy unavailable'));break;
case 'assistant-result':state.mount=state.assistant[2];state.source='Part Pilot · Candidate';state.expanded=true;navigate('focused');break;
case 'engineering-chat':openModal(modalFrame('Chat with Engineering','<p>Engineering chat preview</p><p class="small-gap">This is where you’ll connect with Engineering for configuration questions. Live chat is not connected in this prototype.</p>','M-CSR-ENGINEERING-CHAT'));break;
case 'csr-sample':openModal(modalFrame('CSR Automate · Revision selection',`<p>Sample project · Illustrative data</p>${select('Revision','revision',['Revision 1','Revision 2','Revision 3'],'Revision 1')}<div class="note">After revision selection, eligible project lines would be displayed for an engineering request. This prototype introduces the portal’s starting point only.</div>`));break;
}}
function centerExpandedDetails(){requestAnimationFrame(()=>{const modal=$('#modal');if(modal.open){modal.scrollTo({top:0,behavior:'instant'});return}const detail=document.querySelector('.on-shade-card .accordions');if(detail)detail.scrollIntoView({block:'center',inline:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})})}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const showMore=/^show more detail$/i.test(el.textContent.trim());handle(el.dataset.action,el);if(showMore)centerExpandedDetails()});
document.addEventListener('click',e=>{const row=e.target.closest('[data-quote-line]');if(row&&!e.target.closest('input,label,button,a'))row.querySelector('input[name="line"]').click()});
document.addEventListener('toggle',e=>{const el=e.target;if(el.matches?.('[data-component-line]')&&el.isConnected){const id=Number(el.dataset.componentLine);if(el.open)componentView.openLines.add(id);else componentView.openLines.delete(id);syncCurrentView()}},true);
document.addEventListener('input',e=>{if(['query','entryquery'].includes(e.target.id)){if(e.target.id==='query'){state.query=e.target.value;state.mount=null;state.expanded=false;updateDirectoryResults()}suggestions(e.target)}});
document.addEventListener('focusin',e=>{if(['query','entryquery'].includes(e.target.id)&&e.target.value.trim())suggestions(e.target)});
document.addEventListener('keydown',e=>{if(!['query','entryquery'].includes(e.target.id))return;const input=e.target,box=$('#'+input.id+'-suggestions');if(e.key==='Escape'){closeSuggestions();return}if(box.hidden)return;const options=[...box.querySelectorAll('[role="option"]')];if(['ArrowDown','ArrowUp'].includes(e.key)&&options.length){e.preventDefault();searchActive=searchActive<0?(e.key==='ArrowDown'?0:options.length-1):(searchActive+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((o,i)=>o.setAttribute('aria-selected',String(i===searchActive)));input.setAttribute('aria-activedescendant',options[searchActive].id);options[searchActive].scrollIntoView({block:'nearest'})}if(e.key==='Enter'&&searchActive>=0&&options[searchActive]){e.preventDefault();handle('search-pick',options[searchActive])}});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))closeSuggestions()});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form'){state.email=$('#email').value;navigate('home')}if(e.target.id==='entry-search'){const query=$('#entryquery').value;state.source='Parts directory';navigate('directory',query)}if(e.target.id==='directory-search'){state.query=$('#query').value;closeSuggestions();updateDirectoryResults()}if(e.target.id==='size-form'){state.assistant.push($('#size').value);$('#modal').close();render()}if(e.target.id==='csr-form'){openModal(modalFrame('Project lookup preview',`<p>Project ID: <b>${esc($('#project-id').value)}</b></p><p class="small-gap">The live portal would retrieve revisions directly from the projects interface.</p>${btn('Preview revision selection','csr-sample','primary','style="margin-top:20px"')}`))}});
document.addEventListener('change',e=>{const el=e.target;if(el.closest('.bracket-selection-modal')&&['includeShade','includeSub'].includes(el.dataset.field)){const field=el.dataset.field;state[field]=el.checked;showBracketSelection(true);$('#modal [data-field="'+field+'"]')?.focus({preventScroll:true});return}if(el.name==='line'||el.id==='select-all-lines'){const scrollTop=$('.quote-line-table')?.scrollTop||0,checked=el.checked,id=Number(el.value);if(el.id==='select-all-lines')state.selectedLines=checked?quoteLines.map(line=>line.id):[];else state.selectedLines=quoteLines.filter(line=>line.id===id?checked:state.selectedLines.includes(line.id)).map(line=>line.id);if(!state.selectedLines.includes(state.line))state.line=state.selectedLines[0]??null;render();$('.quote-line-table').scrollTop=scrollTop;document.querySelector(el.id==='select-all-lines'?'#select-all-lines':'input[name="line"][value="'+id+'"]')?.focus({preventScroll:true})}if(el.dataset.field&&el.id!=='revision'){if(state.page==='directory'){state.mount=null;state.expanded=false}state[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;render()}if(el.hasAttribute('data-qty')){const item=state.cart[Number(el.dataset.qty)];if(item)item.qty=Math.min(999,Math.max(1,Number(el.value)||1));renderCart()}if(el.id==='quote-file'&&el.files[0]){state.quoteName=el.files[0].name;startQuote()}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.target.closest('#dropzone')){e.preventDefault();const f=e.dataTransfer.files[0];if(f){state.quoteName=f.name;startQuote()}}});
window.addEventListener('scroll',()=>{if(currentView)currentView.scroll=window.scrollY},{passive:true});
$('#modal').addEventListener('close',()=>{if(!$('#modal').open){modalHistory=[];currentModalState=null}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'inspect_replacement_prototype',description:'Read the current prototype screen, selected mount and replacement list.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({page:state.page,mount:state.mount,parts:state.cart.map(x=>({partNumber:x.code,quantity:x.qty,unit:x.unit}))})})}catch(e){console.warn('Optional model context unavailable')}}
render();
